from functools import lru_cache

class Solution:
    def canMouseWin(self, grid: List[str], catJump: int, mouseJump: int) -> bool:
        rows, cols = len(grid), len(grid[0])

        def moves(pos, jump):
            out = [pos]
            r, c = divmod(pos, cols)
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                for step in range(1, jump + 1):
                    nr, nc = r + dr * step, c + dc * step
                    if not (0 <= nr < rows and 0 <= nc < cols) or grid[nr][nc] == "#":
                        break
                    out.append(nr * cols + nc)
            return out

        mi = ci = fi = 0
        for p in range(rows * cols):
            ch = grid[p // cols][p % cols]
            if ch == "M":
                mi = p
            elif ch == "C":
                ci = p
            elif ch == "F":
                fi = p

        mm = [moves(p, mouseJump) for p in range(rows * cols)]
        cm = [moves(p, catJump) for p in range(rows * cols)]
        cap = 2 * rows * cols

        @lru_cache(maxsize=None)
        def dfs(m, c, t):
            if m == fi:
                return True
            if m == c or c == fi:
                return False
            if t >= cap:
                return False
            if t % 2 == 0:
                return any(dfs(nm, c, t + 1) for nm in mm[m])
            return all(dfs(m, nc, t + 1) for nc in cm[c])

        return dfs(mi, ci, 0)

