    int S, fi, cap;
    vector<vector<int>> mm, cm;
    vector<signed char> memo;

    int dfs(int m, int c, int turn) {
        if (m == fi) return 1;
        if (m == c || c == fi) return 0;
        int key = (m * S + c) * (cap + 1) + turn;
        signed char& slot = memo[key];
        if (slot != -1) return slot;
        int res;
        if (turn >= cap) {
            res = 0;
        } else if (turn % 2 == 0) {
            res = 0;
            for (int nm : mm[m])
                if (dfs(nm, c, turn + 1)) { res = 1; break; }
        } else {
            res = 1;
            for (int nc : cm[c])
                if (!dfs(m, nc, turn + 1)) { res = 0; break; }
        }
        return slot = res;
    }

