class Solution {
    private int S, fi, cap;
    private int[][] mm, cm;
    private byte[] memo;

    public boolean canMouseWin(String[] grid, int catJump, int mouseJump) {
        int rows = grid.length, cols = grid[0].length();
        S = rows * cols;
        int mi = 0, ci = 0;
        fi = 0;
        for (int p = 0; p < S; p++) {
            char ch = grid[p / cols].charAt(p % cols);
            if (ch == 'M') mi = p;
            else if (ch == 'C') ci = p;
            else if (ch == 'F') fi = p;
        }
        mm = buildMoves(grid, rows, cols, S, mouseJump);
        cm = buildMoves(grid, rows, cols, S, catJump);
        cap = 2 * S;
        memo = new byte[S * S * (cap + 1)];
        Arrays.fill(memo, (byte) -1);
        return dfs(mi, ci, 0) == 1;
    }

    private int dfs(int m, int c, int turn) {
        if (m == fi) return 1;
        if (m == c || c == fi) return 0;
        int key = (m * S + c) * (cap + 1) + turn;
        if (memo[key] != -1) return memo[key];
        int res;
        if (turn >= cap) {
            res = 0;
        } else if (turn % 2 == 0) {
            res = 0;
            for (int nm : mm[m])
                if (dfs(nm, c, turn + 1) == 1) { res = 1; break; }
        } else {
            res = 1;
            for (int nc : cm[c])
                if (dfs(m, nc, turn + 1) != 1) { res = 0; break; }
        }
        return memo[key] = (byte) res;
    }

    private int[][] buildMoves(String[] grid, int rows, int cols, int S, int jump) {
        int[][] out = new int[S][];
        int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
        for (int p = 0; p < S; p++) {
            List<Integer> list = new ArrayList<>();
            list.add(p);
            int r = p / cols, c = p % cols;
            for (int k = 0; k < 4; k++)
                for (int step = 1; step <= jump; step++) {
                    int nr = r + dr[k] * step, nc = c + dc[k] * step;
                    if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || grid[nr].charAt(nc) == '#') break;
                    list.add(nr * cols + nc);
                }
            int[] arr = new int[list.size()];
            for (int i = 0; i < arr.length; i++) arr[i] = list.get(i);
            out[p] = arr;
        }
        return out;
    }
}

