class Solution:
    def canMouseWin(self, grid: List[str], catJump: int, mouseJump: int) -> bool:
        rows, cols = len(grid), len(grid[0])
        S = rows * cols

        def moves(pos, jump):
            out = [pos]
            r, c = divmod(pos, cols)
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                for step in range(1, jump + 1):
                    nr, nc = r + dr * step, c + dc * step
                    if not (0 <= nr < rows and 0 <= nc < cols) or grid[nr][nc] == "#":
                        break
                    out.append(nr * cols + nc)
            return out

        mi = ci = fi = 0
        open_cells = []
        for p in range(S):
            ch = grid[p // cols][p % cols]
            if ch != "#":
                open_cells.append(p)
            if ch == "M":
                mi = p
            elif ch == "C":
                ci = p
            elif ch == "F":
                fi = p

        mm = [moves(p, mouseJump) for p in range(S)]
        cm = [moves(p, catJump) for p in range(S)]

        MOUSE, CAT = 1, 2
        total = S * S * 2
        res = [0] * total
        deg = [0] * total
        queue = deque()
        for m in open_cells:
            for c in open_cells:
                for turn in range(2):
                    st = (m * S + c) * 2 + turn
                    if m == fi:
                        res[st] = MOUSE
                    elif m == c or c == fi:
                        res[st] = CAT
                    else:
                        deg[st] = len(mm[m] if turn == 0 else cm[c])
                        continue
                    queue.append(st)

        while queue:
            st = queue.popleft()
            m, rest = divmod(st, 2 * S)
            c, turn = divmod(rest, 2)
            prev = 1 - turn
            for np_ in (mm[m] if prev == 0 else cm[c]):
                pst = ((np_ * S + c) if prev == 0 else (m * S + np_)) * 2 + prev
                if res[pst]:
                    continue
                if res[st] == (MOUSE if prev == 0 else CAT):
                    res[pst] = res[st]
                    queue.append(pst)
                else:
                    deg[pst] -= 1
                    if deg[pst] == 0:
                        res[pst] = res[st]
                        queue.append(pst)
        return res[(mi * S + ci) * 2] == MOUSE

