            for (int c : openCells)
                for (int turn = 0; turn < 2; ++turn) {
                    int st = (m * S + c) * 2 + turn;
                    if (m == fi) res[st] = MOUSE;
                    else if (m == c || c == fi) res[st] = CAT;
                    else {
                        deg[st] = (turn == 0 ? mm[m] : cm[c]).size();
                        continue;
                    }
