class Solution {
    public boolean canMouseWin(String[] grid, int catJump, int mouseJump) {
        int rows = grid.length, cols = grid[0].length(), S = rows * cols;
        int mi = 0, ci = 0, fi = 0;
        List<Integer> openCells = new ArrayList<>();
        for (int p = 0; p < S; p++) {
            char ch = grid[p / cols].charAt(p % cols);
            if (ch != '#') openCells.add(p);
            if (ch == 'M') mi = p;
            else if (ch == 'C') ci = p;
            else if (ch == 'F') fi = p;
        }
        int[][] mm = buildMoves(grid, rows, cols, S, mouseJump);
        int[][] cm = buildMoves(grid, rows, cols, S, catJump);
        final int MOUSE = 1, CAT = 2;
        int total = S * S * 2;
        int[] res = new int[total], deg = new int[total];
        Queue<Integer> queue = new ArrayDeque<>();
        for (int m : openCells)
            for (int c : openCells)
                for (int turn = 0; turn < 2; turn++) {
                    int st = (m * S + c) * 2 + turn;
                    if (m == fi) res[st] = MOUSE;
                    else if (m == c || c == fi) res[st] = CAT;
                    else {
                        deg[st] = (turn == 0 ? mm[m] : cm[c]).length;
                        continue;
                    }
                    queue.offer(st);
                }
        while (!queue.isEmpty()) {
            int st = queue.poll();
            int m = st / (2 * S), rest = st % (2 * S);
            int c = rest / 2, turn = rest % 2;
            int prev = 1 - turn;
            for (int np : (prev == 0 ? mm[m] : cm[c])) {
                int pst = (prev == 0 ? np * S + c : m * S + np) * 2 + prev;
                if (res[pst] != 0) continue;
                if (res[st] == (prev == 0 ? MOUSE : CAT)) {
                    res[pst] = res[st];
                    queue.offer(pst);
                } else if (--deg[pst] == 0) {
                    res[pst] = res[st];
                    queue.offer(pst);
                }
            }
        }
        return res[(mi * S + ci) * 2] == MOUSE;
    }

    private int[][] buildMoves(String[] grid, int rows, int cols, int S, int jump) {
        int[][] out = new int[S][];
        int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
        for (int p = 0; p < S; p++) {
            List<Integer> list = new ArrayList<>();
            list.add(p);
            int r = p / cols, c = p % cols;
            for (int k = 0; k < 4; k++)
                for (int step = 1; step <= jump; step++) {
                    int nr = r + dr[k] * step, nc = c + dc[k] * step;
                    if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || grid[nr].charAt(nc) == '#') break;
                    list.add(nr * cols + nc);
                }
            int[] arr = new int[list.size()];
            for (int i = 0; i < arr.length; i++) arr[i] = list.get(i);
            out[p] = arr;
        }
        return out;
    }
}

